#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "$0")" && pwd)"
APP="$ROOT/laravel-app"
if [ ! -f "$APP/artisan" ]; then
  echo "Laravel app not found: $APP"
  exit 1
fi
mkdir -p "$APP/resources/views"
cat > "$APP/resources/views/welcome.blade.php" <<'BLADE'
